// v23.xx (spr5): a soft glow disc baked once per colour (a radial gradient on a small canvas), stamped with drawImage, so a
// glow costs one image draw instead of building a gradient every frame.
var SPRGLOW={};
function sprGlow(c){
  var k=c, cv2, g2, gr;
  if(SPRGLOW[k]) return SPRGLOW[k];
  if(typeof document==='undefined') return null;
  cv2=document.createElement('canvas'); cv2.width=64; cv2.height=64; g2=cv2.getContext('2d'); if(!g2) return null;
  gr=g2.createRadialGradient(32,32,1,32,32,32); gr.addColorStop(0,c); gr.addColorStop(1,'rgba(0,0,0,0)');
  g2.fillStyle=gr; g2.fillRect(0,0,64,64);
  SPRGLOW[k]=cv2; return cv2;
}
function drawListenerS(e){
  // Nothing else on this map is this shape. Tall, thin, no face, arms too long,
  // and a wide dish where a head should be. Dormant it is nearly black and
  // hunched, so at a glance it is a bit of standing scrap; awake it straightens
  // up, which is the moment you are meant to feel.
  // v23.xx (spr5), HIS ORDER (2026-10-12): "improve the sprites of all characters, bots, etc", gritty and grounded like ARC
  // Raiders, silhouettes first. The sprite program, MACHINES A, build 4: THE LISTENER. The strongest idea and the weakest draw:
  // a stick man with a satellite dish, limbs two or three pixels wide on a laptop. Kept tall, thin and faceless, it is redrawn:
  // digitigrade stilt legs (thigh forward, shin back, a hoof), long arms to the knee ending in three hooked fingers, a narrow
  // ribbed spine, and a big dish with a raised rim lit from the top left, a ring of five sensor pits and two swept fins behind it
  // ears. Dormant it hunches near black with only the rim catching light; awake it straightens, the pits light red one after
  // another round the ring and the dish centre is its red eye. The glow is a disc baked once (sprGlow), not a gradient built
  // every frame. An elite has a brass rim and a third fin. Drawn only: no random numbers, its size and shadow as before.
  var dorm=(e.state==='dormant'), fl=Math.cos(e.face)<0?-1:1, t=(typeof G!=='undefined'&&G)?(G.t||0):0, i, k, s;
  var h=dorm?26:40, lg=e.legs||0, sway=Math.sin(lg*0.6)*(dorm?0.6:2.2), brass=!!e.elite, x=e.x, y=e.y;
  var body=dorm?'#1d2028':'#3e454c', lit=dorm?'#2c313a':'#59626b', shade=dorm?'#15171c':'#2a2f35';
  shadowE(x,y+1,10,4,.40);
  wc.lineCap='round'; wc.lineJoin='round';
  // THE LEGS: digitigrade stilts, the far one first; thigh forward to the knee, shin back to a high heel, a hoof planted
  for(s=1;s>=-1;s-=2){
    var hx=x+s*2.4, st=Math.sin(lg+(s>0?0:Math.PI))*1.6*(dorm?0.3:1);
    var P=[hx,y-h*0.46, hx+fl*(3.4+st*0.5),y-h*0.29, hx-fl*(1.8-st*0.6),y-h*0.12, hx+fl*(0.8+st),y];
    wc.strokeStyle=INK; wc.lineWidth=4.6; wc.beginPath(); wc.moveTo(P[0],P[1]); wc.lineTo(P[2],P[3]); wc.lineTo(P[4],P[5]); wc.lineTo(P[6],P[7]); wc.stroke();
    wc.strokeStyle=(s>0)?shade:body; wc.lineWidth=2.8; wc.stroke();
    wc.fillStyle=INK; wc.fillRect(P[6]-2.4,y-1.8,4.8,2.2);
    wc.fillStyle=lit; wc.fillRect(P[2]-0.7,P[3]-0.7,1.4,1.4);
  }
  // THE SPINE: a narrow inked torso, lit down its left edge, three rib seams
  var tx=x+sway*0.3, ty=y-h;
  wc.fillStyle=INK; rrF(tx-5.2,ty,10.4,h*0.58,3);
  wc.fillStyle=body; rrF(tx-4.2,ty+1,8.4,h*0.56,2.4);
  wc.fillStyle=lit; wc.fillRect(tx-4.2,ty+2,1.4,h*0.5);
  wc.fillStyle=shade; wc.fillRect(tx+2.6,ty+2,1.6,h*0.5);
  for(k=0;k<3;k++) wc.fillRect(tx-3,ty+h*(0.16+k*0.12),6,1.1);
  // THE ARMS: long, to the knee, three hooked fingers at each hand
  for(s=-1;s<=1;s+=2){
    var ax=x+s*6.6+sway, ay=y-h+3, ex2=ax+s*0.6, ey2=y-h*0.33;
    wc.strokeStyle=INK; wc.lineWidth=4.2; wc.beginPath(); wc.moveTo(ax,ay); wc.lineTo(ax+s*1.2,ay+h*0.3); wc.lineTo(ex2,ey2); wc.stroke();
    wc.strokeStyle=(s>0)?shade:body; wc.lineWidth=2.4; wc.stroke();
    wc.strokeStyle=INK; wc.lineWidth=1.2; wc.beginPath();
    for(k=-1;k<=1;k++){ wc.moveTo(ex2+k*1.1,ey2); wc.quadraticCurveTo(ex2+k*1.5,ey2+2.6,ex2+k*1.1+fl*1.2,ey2+3.2); }
    wc.stroke();
  }
  // THE DISH where a face should be: fins behind it, an inked rim lit at the top left, five sensor pits round an inner ring
  var dx=x+sway*1.2, dy=y-h-(dorm?2:7);
  wc.fillStyle=INK;
  for(s=-1;s<=1;s+=2){ wc.beginPath(); wc.moveTo(dx+s*5,dy-1.5); wc.lineTo(dx+s*13.6,dy-4.8); wc.lineTo(dx+s*8.8,dy+2.0); wc.closePath(); wc.fill(); }
  if(brass){ wc.beginPath(); wc.moveTo(dx-2.4,dy-4); wc.lineTo(dx,dy-11.5); wc.lineTo(dx+2.4,dy-4); wc.closePath(); wc.fill(); }
  wc.fillStyle=dorm?'#2a2f38':'#4a525b';
  for(s=-1;s<=1;s+=2){ wc.beginPath(); wc.moveTo(dx+s*6,dy-1.4); wc.lineTo(dx+s*12.2,dy-4.0); wc.lineTo(dx+s*8.4,dy+1.0); wc.closePath(); wc.fill(); }
  wc.fillStyle=INK; wc.beginPath(); wc.ellipse(dx,dy,9.6,6.4,0,0,6.2832); wc.fill();
  wc.fillStyle=dorm?'#242833':'#59626b'; wc.beginPath(); wc.ellipse(dx,dy,8.4,5.4,0,0,6.2832); wc.fill();
  wc.strokeStyle=brass?'#c9a24a':(dorm?'#4a525b':'#9aa4ad'); wc.lineWidth=1.2;
  wc.beginPath(); wc.ellipse(dx,dy,7.8,4.9,0,3.3,5.3); wc.stroke();
  wc.fillStyle=dorm?'#15171c':'#2a2f35'; wc.beginPath(); wc.ellipse(dx,dy+0.4,6.2,3.8,0,0,6.2832); wc.fill();
  var lit5=dorm?-1:Math.floor((t*4)%6);
  for(k=0;k<5;k++){
    var pa=-1.5708+k*1.2566, ppx=dx+Math.cos(pa)*4.4, ppy=dy+0.4+Math.sin(pa)*2.6;
    wc.fillStyle=INK; wc.beginPath(); wc.arc(ppx,ppy,1.05,0,6.2832); wc.fill();
    if(!dorm&&k<=lit5){ wc.fillStyle='#ff5a4a'; wc.beginPath(); wc.arc(ppx,ppy,0.6,0,6.2832); wc.fill(); }
  }
  if(!dorm){
    var pl=0.55+0.45*Math.sin(t*7), gd=sprGlow('#ff5a4a');
    if(gd){ wc.save(); wc.globalCompositeOperation='lighter'; wc.globalAlpha=0.45*pl; wc.drawImage(gd,dx-12,dy+0.4-12,24,24); wc.restore(); }
    wc.fillStyle=INK; wc.beginPath(); wc.arc(dx,dy+0.4,1.9,0,6.2832); wc.fill();
    wc.fillStyle='#ff5a4a'; wc.beginPath(); wc.arc(dx,dy+0.4,1.3,0,6.2832); wc.fill();
    wc.fillStyle='rgba(255,255,255,.8)'; wc.fillRect(dx-0.9,dy-0.6,0.6,0.6);
  }
  wc.lineCap='butt'; wc.lineJoin='miter';
}

