   function paint(e){ x2.setTransform(1,0,0,1,0,0); x2.clearRect(0,0,360,420); x2.setTransform(6,0,0,6,180,390); wc=x2;
     try{ drawListenerS(e); } finally { wc=w0; x2.setTransform(1,0,0,1,0,0); } }
