   finally{ wc=w0; try{ delete x2.createRadialGradient; }catch(_d){} try{ if(t0!==null&&G) G.t=t0; }catch(_g){} if(staged){ try{ __endRaid('abandon'); }catch(_e){} try{ __topClear(); }catch(_t){} } }
   return bad.length?bad.join('; '):null; }},
